test('new output falls back to verified copy when Windows refuses the stage directory rename', () => {
  const fixture = makeFixture(); const inspection = inspectGbStudioExport({ projectDir: fixture.root, settings: { warningsAcknowledged: true }, gbStudio: GB_STUDIO }); assert.equal(inspection.ok, true, JSON.stringify(inspection.errors)); const outputDir = path.join(fixture.root, 'gb-output-copy-fallback'); const originalRename = fs.renameSync; let injected = false;
  fs.renameSync = (source, destination) => { if (!injected && path.basename(String(source)).startsWith('.pce-vn-gb-stage-') && path.resolve(destination) === path.resolve(outputDir)) { injected = true; const error = new Error('simulated Windows directory lock'); error.code = 'EPERM'; throw error; } return originalRename(source, destination); };
  try { const result = generateGbStudioProject({ inspection, outputDir }); assert.equal(injected, true); assert.equal(result.commitMode, 'copy-fallback'); assert.equal(result.validation.ok, true, JSON.stringify(result.validation.errors)); assert.ok(fs.existsSync(result.descriptorPath)); } finally { fs.renameSync = originalRename; }
});

