test('baked visual controller preserves four logical slots, A/B replacement state, animation loops, moves, SpriteText blink, and effects', () => {
  const fixture = makeFixture(); addSpriteAsset(fixture, { frameCount: 2, delays: [10, 2] }); fixture.scenes = { version: 2, startScene: 'opening', scenes: [{ id: 'opening', commands: [
    { type: 'background', assetId: 'bg' }, { type: 'sprite', slot: 0, assetId: 'portrait', x: 0, y: 10, visible: true }, { type: 'sprite', slot: 1, assetId: 'portrait', x: 80, y: 12, flipY: true, visible: true }, { type: 'sprite', slot: 2, assetId: 'portrait', x: 160, y: 14, visible: true }, { type: 'sprite', slot: 3, assetId: 'portrait', x: 240, y: 16, visible: true }, { type: 'spritemove', slot: 0, x: 120, y: 30, frames: 30, async: true }, { type: 'spritemove', slot: 1, x: 140, y: 32, frames: 45, async: false }, { type: 'spritetext', slot: 0, text: '右端から欠落なく折り返す', x: 312, y: 8, color: '#ff8040', blinkFrames: 4 }, { type: 'effect', effect: 'fadeOut', frames: 15 }, { type: 'effect', effect: 'fadeIn', frames: 25 }, { type: 'effect', effect: 'flash', color: '#f08020', frames: 7 }, { type: 'effect', effect: 'shake', intensity: 2, frames: 9 }, { type: 'effect', effect: 'blank', frames: 0 }, { type: 'background', assetId: 'bg' }, { type: 'sprite', slot: 0, assetId: 'portrait', x: 20, y: 10, visible: true }, { type: 'spritemove', slot: 0, x: 60, y: 20, frames: 60, async: true }, { type: 'spritemove', slot: 1, x: 200, y: 36, frames: 90, async: false }, { type: 'message', text: '完了' },
  ] }] }; fs.writeFileSync(path.join(fixture.root, 'assets', 'pce-vn-scenes.json'), JSON.stringify(fixture.scenes));
  const inspection = inspectGbStudioExport({ projectDir: fixture.root, settings: { portraitRenderMode: 'baked', warningsAcknowledged: true }, gbStudio: GB_STUDIO_432 }); assert.equal(inspection.ok, true, JSON.stringify(inspection.errors)); assert.equal(inspection.audits.visual.omissions.length, 0); assert.ok(inspection.audits.visual.loops.some((loop) => loop.tracks.sprites.length > 0)); assert.ok(inspection.audits.visual.loops.some((loop) => loop.tracks.spriteTexts.length > 0)); assert.ok(inspection.audits.visual.approximations.some((entry) => entry.kind === 'visual-command-mapping' && entry.effect?.effect === 'flash' && entry.effect.generatedColor === '#ffffff')); assert.ok(inspection.audits.visual.approximations.some((entry) => entry.kind === 'visual-command-mapping' && entry.effect?.effect === 'fadeOut' && entry.effect.generatedFrames === 10)); const state = inspection._model.graph.segments.flatMap((segment) => segment.visualPlans).find((plan) => plan.evictedSlot != null); assert.ok(state, 'A/B循環でevictedSlotを監査する'); const spriteTextPlan = inspection._model.graph.segments.flatMap((segment) => segment.visualPlans).find((plan) => plan.type === 'spritetext' && plan.action === 'text-show'); assert.equal(spriteTextPlan.spriteText.content, '右端から欠落なく折り返す'); assert.equal(spriteTextPlan.spriteText.generatedPosition.x, 152); assert.equal(spriteTextPlan.spriteText.positionFidelity, 'approximated'); const movePlans = inspection._model.graph.segments.flatMap((segment) => segment.visualPlans).filter((plan) => plan.type === 'spritemove'); const syncPlan = movePlans.find((plan) => plan.move.frames === 45); assert.equal(syncPlan.beforeState.sprites[0].x, 0); assert.equal(syncPlan.renderAfterState.sprites[0].x, 120); assert.equal(syncPlan.renderAfterState.sprites[1].x, 140); assert.deepEqual([...new Set(movePlans.map((plan) => plan.move.frames))].sort((a, b) => a - b), [30, 45, 60, 90]); assert.equal(new Set(movePlans.map((plan) => plan.timelineId)).size, 2, '各async+sync群を1本の合成timelineへ統合する'); assert.deepEqual(movePlans.map((plan) => plan.coalescedRole), ['group-start', 'group-sync', 'group-start', 'group-sync']); const moveGroups = inspection.audits.visual.timelines.filter((timeline) => timeline.kind === 'spritemove-group'); assert.equal(moveGroups.length, 2); assert.ok(moveGroups.every((timeline) => timeline.coalescedSourceKeys.length === 2 && Object.values(timeline.modes).every((mode) => mode.syncRenderedFrames >= mode.syncSourceFrames))); const longSync = movePlans.find((plan) => plan.move.frames === 90); assert.equal(longSync.renderAfterState.sprites[0].x, 60); assert.equal(longSync.renderAfterState.sprites[1].x, 200);
  const outputDir = path.join(fixture.root, 'gb-output-baked'); const generated = generateGbStudioProject({ inspection, outputDir }); const eventRows = generatedEvents(outputDir); const events = eventRows.map(({ event }) => event.command); ['EVENT_REPLACE_TILE_XY', 'EVENT_CALL_CUSTOM_EVENT', 'EVENT_ACTOR_START_UPDATE', 'EVENT_ACTOR_STOP_UPDATE', 'EVENT_FADE_OUT', 'EVENT_FADE_IN', 'EVENT_OVERLAY_SHOW', 'EVENT_OVERLAY_HIDE', 'EVENT_CAMERA_SHAKE'].forEach((command) => assert.ok(events.includes(command), command)); const visualAudit = JSON.parse(fs.readFileSync(path.join(outputDir, 'build', 'qa', 'visual-audit.json'), 'utf-8')); assert.equal(visualAudit.status, 'pass'); assert.equal(visualAudit.omissions.length, 0); assert.ok(visualAudit.loops.every((loop) => Object.values(loop.modes).every((mode) => mode.generatedTiles <= 256 && mode.maxTilesPerFrame === 32))); const progressVariable = inspection._model.variables.ids.__pce_vn_visual_progress; assert.ok(progressVariable); const progressModes = visualAudit.timelines.filter((timeline) => timeline.async).flatMap((timeline) => Object.values(timeline.modes)).filter((mode) => mode.progress); assert.ok(progressModes.length >= 2); assert.ok(progressModes.every((mode) => mode.progress.variableId === progressVariable && mode.progress.keyframes.every((entry) => entry.code > mode.progress.initialCode))); assert.ok(eventRows.some(({ event }) => event.command === 'EVENT_SET_VALUE' && event.args.variable === progressVariable && Number(event.args.value?.value) > 0)); assert.equal(generated.stats.visualTileBanks, visualAudit.tileBanks.length); assert.ok(visualAudit.tileBanks.every((bank) => bank.tiles <= 256 && bank.artifacts >= 1)); const visualScripts = fs.readdirSync(path.join(outputDir, 'project', 'scripts', 'pce-vn-visual')).filter((name) => name.endsWith('.gbsres')).map((name) => JSON.parse(fs.readFileSync(path.join(outputDir, 'project', 'scripts', 'pce-vn-visual', name), 'utf-8'))); assert.equal(generated.stats.visualScripts, visualScripts.length); assert.ok(visualScripts.every((script) => script._resourceType === 'script' && script.script.length > 0 && script.script.length <= 160)); const controlAudit = JSON.parse(fs.readFileSync(path.join(outputDir, 'build', 'qa', 'control-flow-audit.json'), 'utf-8')); assert.ok(controlAudit.commands.filter((command) => ['sprite', 'spritemove', 'spritetext', 'effect'].includes(command.normalizedType)).every((command) => command.visual.length > 0)); assert.ok(fs.readdirSync(path.join(outputDir, 'project', 'scenes'), { recursive: true }).some((name) => String(name).endsWith('visual_controller.gbsres')));
});

