test('000_百物語 has no metadata-only unreachable warning and inherits all four branch backgrounds', { skip: !fs.existsSync(path.join(__dirname, '..', 'data', 'projects', 'ホラーストーリー', '000_百物語', 'project.json')) }, () => {
  const projectDir = path.join(__dirname, '..', 'data', 'projects', 'ホラーストーリー', '000_百物語'); const inspection = inspectGbStudioExport({ projectDir, settings: { warningsAcknowledged: true, visualOmissionsConfirmed: true }, gbStudio: GB_STUDIO_432 }); assert.equal(inspection.ok, true, JSON.stringify(inspection.errors)); assert.equal(inspection.warnings.some((entry) => entry.code === 'GBVN_UNREACHABLE_BLOCK'), false); const selectorPrompt = inspection._model.graph.segments.flatMap((segment) => segment.visualPlans).find((plan) => plan.spriteText?.content === '← シナリオ選択 →'); assert.ok(selectorPrompt); assert.equal(selectorPrompt.spriteText.color.rendered, '#000000'); assert.equal(selectorPrompt.spriteText.generatedPosition.y, 104); assert.equal(selectorPrompt.spriteText.policy.titleSceneBlack, true); assert.equal(selectorPrompt.spriteText.policy.systemUiPalette, true); assert.equal(selectorPrompt.spriteText.policy.selectorRowSpacingY, 16); assert.equal(selectorPrompt.spriteText.policy.selectorPromptMarginY, 8); const prologue = inspection._model.graph.segments.find((segment) => segment.key === inspection._model.graph.firstTargets.scene_prologue); assert.ok(prologue); assert.ok(prologue.entryVisualState.spriteTexts.every((entry) => entry == null)); const expected = { scene_tale_isamu_a: 'still_tale_kouichi_01_candlelit_circle', scene_tale_isamu_b: 'still_tale_kouichi_01_candlelit_circle', scene_search_a: 'still_vanish_02_group_waits', scene_search_b: 'still_vanish_02_group_waits' }; for (const [sceneId, background] of Object.entries(expected)) { const variants = inspection._model.graph.segments.filter((segment) => segment.sourceSceneId === sceneId && segment.reachable); assert.ok(variants.length > 0, sceneId); assert.ok(variants.every((segment) => segment.effectiveBackgroundKey === background && segment.backgroundSource === 'inherited'), sceneId); }
  const flatCount = inspection.audits.music.reduce((sum, audit) => sum + audit.normalizedNotes.filter((entry) => /b|♭/.test(entry.source)).length, 0); assert.equal(flatCount, 11); assert.equal(inspection.audits.music.some((audit) => audit.droppedEvents.some((entry) => entry.reason === 'invalid-note')), false);
});
